1	export type Card = {
2	  monster: string;
3	  rank?: number;
4	};
5	
6	const SPHINX = "sphinx";
7	
8	const SPHINX_POINT = 1;
9	const THREE_TYPES = 3;
10	const POINTS_PER_TYPE_BEYOND_THREE = 2;
11	const POINTS_WITHIN_THREE_TYPES = 1;
12	
13	const isSphinx = (card: Card): boolean => card.monster === SPHINX;
14	
15	const countDistinctTypes = (army: Card[]): number =>
16	  new Set(army.map((card) => card.monster)).size;
17	
18	const scoreTypeVariety = (typeCount: number): number =>
19	  typeCount > THREE_TYPES
20	    ? POINTS_PER_TYPE_BEYOND_THREE * (typeCount - THREE_TYPES)
21	    : POINTS_WITHIN_THREE_TYPES;
22	
23	// A Sphinx looks out at the rest of the army: every card except the one it is
24	// standing on. Its own card is dropped by position, not by type — the other
25	// cards of that same type stay, and can still make up a type it sees.
26	const armySeenBySphinxAt = (army: Card[], index: number): Card[] => [
27	  ...army.slice(0, index),
28	  ...army.slice(index + 1),
29	];
30	
31	const scoreSphinxAt = (army: Card[], index: number): number =>
32	  SPHINX_POINT +
33	  scoreTypeVariety(countDistinctTypes(armySeenBySphinxAt(army, index)));
34	
35	export const scoreArmy = (army: Card[]): number =>
36	  army.reduce(
37	    (total, card, index) =>
38	      isSphinx(card) ? total + scoreSphinxAt(army, index) : total,
39	    0,
40	  );
